component.css:
.msv {--ink: #2a3440;--dim: #6b7480;--panel: #f8f0de;--acc: #2d5680;--gold: #b98a2e;position: relative;width: 100%;aspect-ratio: 1672 / 941;container-type: size;overflow: hidden;border-radius: 10px;background: #0d1420;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.msv *, .msv *::before, .msv *::after { box-sizing: border-box; }
.msv button { font-family: inherit; border: 0; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; text-align: left; }
.msv button:focus { outline: none; }
.msv button:focus-visible { outline: 2px solid #4e86b4; outline-offset: 1px; }
.msv-bg { position: absolute; inset: 0; background: url("https://origin.picgo.net/2026/10/21/1000086358709d3ef19b5e4494.png") center / 100% 100% no-repeat; pointer-events: none; }
.msv-slots, .msv-pager { position: absolute; inset: 0; }
.msv-slot {position: absolute; width: 22.7%; height: 23.2%;border-radius: 6px;overflow: hidden;transition: box-shadow .15s;}
@media (hover: hover) {.msv-slot:hover { box-shadow: inset 0 0 0 2px #2d56809c; }}
.msv-slot.is-arm { box-shadow: inset 0 0 0 3px #b98a2ecc; animation: msvArm 1s ease-in-out infinite; }
@keyframes msvArm { 50% { box-shadow: inset 0 0 0 3px #b98a2e66; } }
.msv-slot__in {position: absolute; inset: 7% 8% 6%;display: flex; flex-direction: column; justify-content: space-between;color: var(--ink);}
.msv-slot__top { display: flex; align-items: baseline; gap: 2%; font-size: 1.55cqh; color: var(--dim); }
.msv-slot__top b { font-size: 1.9cqh; color: var(--acc); letter-spacing: .05em; }
.msv-slot__loc {font-size: 2.35cqh; font-weight: 700; color: var(--ink);letter-spacing: .04em;overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
.msv-slot__sub { display: flex; align-items: baseline; gap: 5%; font-size: 1.5cqh; color: var(--dim); }
.msv-slot__sub b { color: #8a5a28; font-weight: 700; }
.msv-slot__scene {font-size: 1.45cqh; line-height: 1.4; color: #4d5661;display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;}
.msv-slot__hint {position: absolute; inset: 0;display: flex; align-items: center; justify-content: center;font-size: 1.7cqh; letter-spacing: .2em;color: #2a344066;pointer-events: none;}
.msv-slot.is-empty:hover .msv-slot__hint { color: #2d5680; }
.msv-pager__btn {position: absolute; top: 84.5%; height: 5%; width: 3.5%; display: flex; align-items: center; justify-content: center;font-size: 2.4cqh; color: var(--ink); border-radius: 4px;}
.msv-pager__btn--num { width: 3.5%; }
.msv-pager__btn--num.is-cur { color: var(--acc); font-weight: 800; text-decoration: underline; text-underline-offset: .5cqh; }
@media (hover: hover) {.msv-pager__btn:hover { background: #2d568024; }}
#msvSave { position: absolute; left: 37%; top: 77.8%; width: 26%; height: 5.4%; border-radius: 8px; }
@media (hover: hover) {#msvSave:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}
#msvBack { position: absolute; left: 1.5%; top: 93%; width: 11.5%; height: 5%; border-radius: 6px; }
@media (hover: hover) {#msvBack:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}

component.script:
"use strict";(() => {
var SL = String.fromCharCode(47);
var Z = n => "<" + String.fromCharCode(36) + n + String.fromCharCode(36) + ">";
var ZE = n => "<" + SL + String.fromCharCode(36) + n + String.fromCharCode(36) + ">";
var et = (open, inner) => "<" + open + ">" + inner + "<" + SL + open.split(" ")[0] + ">";
var root = document.getElementById("msvRoot");
if (!root) return;
var byId = i => document.getElementById(i);
var COLS = [21, 45.3, 69.6];
var ROWS = [25.6, 51.2];
var ROUTES = { A: "A线·秦瑾", B: "B线·林戌岚", C: "C线·乌尔里克" };
var key = n => "都档" + n;
var esc = s => String(s).split("&").join("&amp;").split("<").join("&lt;");
var bridge = typeof readFromLocal === "function" && typeof saveToLocal === "function";
var attr = k => (root.getAttribute("data-" + k) || "").trim();
var routeRaw = attr("route").toUpperCase();
var route = (routeRaw === "A" || routeRaw === "B" || routeRaw === "C") ? routeRaw : "B";
var cg = "";
var rawCg = attr("cg").toUpperCase();
for (var ci = 0; ci < rawCg.length; ci++) {
  var ch = rawCg.charAt(ci);
  if ((ch >= "A" && ch <= "C") || (ch >= "0" && ch <= "8")) cg += ch;
}
var cgCount = 0;
for (var pi = 0; pi + 1 < cg.length; pi += 2) {
  var cl = cg.charAt(pi), cd = cg.charAt(pi + 1);
  if (cl >= "A" && cl <= "C" && cd >= "1" && cd <= "8") cgCount++;
}
var scene = attr("scene").slice(0, 60).split("|").join(" ").split("\n").join(" ").split("\r").join(" ");
var cur = [route, attr("day") || "D1", attr("time") || "--:--", attr("loc") || "未知", attr("dragon"), attr("tiger"), attr("wolf"), attr("thirst") || "0", attr("hunger") || "0", cg, scene];
var serialize = () => cur.join("|");
var parse = v => { var p = (v || "").split("|"); return p.length === 11 ? p : null; };
var readSlot = n => {
  if (bridge) return Promise.resolve(readFromLocal(key(n))).catch(() => "");
  try { return Promise.resolve(localStorage.getItem(key(n)) || ""); } catch (e) { return Promise.resolve(""); }
};
var writeSlot = (n, v) => {
  if (bridge) return Promise.resolve(saveToLocal(key(n), v)).then(() => true).catch(() => false);
  try { localStorage.setItem(key(n), v); return Promise.resolve(true); } catch (e) { return Promise.resolve(false); }
};
var page = 0;
var armed = {};
var render = () => {
  var box = byId("msvSlots");
  box.innerHTML = "";
  for (var i = 0; i < 6; i++) {
    (function (idx) {
      var slotNo = page * 6 + idx + 1;
      var cell = document.createElement("button");
      cell.className = "msv-slot";
      cell.style.left = COLS[idx % 3] + "%";
      cell.style.top = ROWS[idx < 3 ? 0 : 1] + "%";
      cell.setAttribute("aria-label", "存档-" + slotNo);
      box.appendChild(cell);
      readSlot(slotNo).then(v => {
        var d = parse(v);
        if (!d) {
          cell.className += " is-empty";
          cell.innerHTML = et('span class="msv-slot__hint"', "+ 存入此处");
          cell.addEventListener("click", () => {
            writeSlot(slotNo, serialize()).then(ok => {
              toast(ok ? "已保存到 存档 " + (page + 1) + "-" + (idx + 1) : "保存失败：本地存储不可用");
              if (ok) render();
            });
          });
          return;
        }
        var aff = d[4] !== "-" && d[4] !== "" ? d[4] : (d[5] !== "-" && d[5] !== "" ? d[5] : d[6]);
        var dcg = 0;
        for (var k = 0; k + 1 < (d[9] || "").length; k += 2) {
          var a = d[9].charAt(k), b = d[9].charAt(k + 1);
          if (a >= "A" && a <= "C" && b >= "1" && b <= "8") dcg++;
        }
        cell.innerHTML =
          et('div class="msv-slot__in"',
            et('div class="msv-slot__top"',
              et("b", ROUTES[d[0]] || d[0]) + et("span", d[1] + " " + d[2])) +
            et('div class="msv-slot__loc"', esc(d[3])) +
            et('div class="msv-slot__sub"',
              et("span", "好感 " + et("b", aff)) +
              et("span", "渴" + d[7] + " 饿" + d[8]) +
              et("span", "CG×" + dcg)) +
            et('div class="msv-slot__scene"', esc(d[10])));
        cell.addEventListener("click", () => {
          var t = armed[slotNo] || 0;
          if (Date.now() - t < 3000) {
            delete armed[slotNo];
            writeSlot(slotNo, serialize()).then(ok => {
              toast(ok ? "已覆盖 存档 " + (page + 1) + "-" + (idx + 1) : "保存失败：本地存储不可用");
              if (ok) render();
            });
          } else {
            armed[slotNo] = Date.now();
            cell.classList.add("is-arm");
            toast("再次点击以覆盖 存档 " + (page + 1) + "-" + (idx + 1));
            setTimeout(() => cell.classList.remove("is-arm"), 3000);
          }
        });
      });
    })(i);
  }
  var pager = byId("msvPager");
  pager.innerHTML = "";
  var mk = (txt, cls, fn) => {
    var b = document.createElement("button");
    b.className = "msv-pager__btn " + cls;
    b.textContent = txt;
    b.addEventListener("click", fn);
    pager.appendChild(b);
  };
  mk("‹", "", () => { page = (page + 2) % 3; render(); });
  for (var n = 0; n < 3; n++) (function (num) {
    mk(String(num + 1), "msv-pager__btn--num" + (num === page ? " is-cur" : ""), () => { page = num; render(); });
  })(n);
  mk("›", "", () => { page = (page + 1) % 3; render(); });
  var pos = [42.65, 44.25, 48.25, 52.25, 54.85];
  var kids = pager.children;
  for (var j = 0; j < kids.length; j++) kids[j].style.left = pos[j] + "%";
};
render();
byId("msvSave").addEventListener("click", () => {
  var trySlot = i => {
    if (i > 6) { toast("当前页已满 —— 请点击槽位覆盖，或翻到新页"); return; }
    var slotNo = page * 6 + i;
    readSlot(slotNo).then(v => {
      if (parse(v)) trySlot(i + 1);
      else writeSlot(slotNo, serialize()).then(ok => {
        toast(ok ? "已保存到 存档 " + (page + 1) + "-" + i : "保存失败：本地存储不可用");
        if (ok) render();
      });
    });
  };
  trySlot(1);
});
byId("msvBack").addEventListener("click", () => {
  changeMsg("" + Z("大都会标题页") + et("页面", "标题") + et("动画", "完成") + et("状态", "") + ZE("大都会标题页"));
});
})();
